class Solution:
    def minimumMoves(self, s: str) -> int:
        s = list(s)
        ans = 0
        while s:
            j = len(s) - 1 - s[::-1].index(s[0])
            if j == 0:
                s.pop(0)
                continue
            ans += len(s) - 1 - j
            del s[j]
            del s[0]
        return ans

