class Solution {
public:
    int minimumMoves(string s) {
        int ans = 0;
        while (!s.empty()) {
            size_t j = s.rfind(s[0]);
            if (j == 0) { s.erase(s.begin()); continue; }
            ans += (int)s.size() - 1 - (int)j;
            s.erase(j, 1);
            s.erase(0, 1);
        }
        return ans;
    }
};

