class Solution {
    public int minimumMoves(String str) {
        StringBuilder sb = new StringBuilder(str);
        int ans = 0;
        while (sb.length() > 0) {
            int j = sb.lastIndexOf(String.valueOf(sb.charAt(0)));
            if (j == 0) { sb.deleteCharAt(0); continue; }
            ans += sb.length() - 1 - j;
            sb.deleteCharAt(j);
            sb.deleteCharAt(0);
        }
        return ans;
    }
}

