var minimumMoves = function(s) {
    let arr = s.split(''), ans = 0;
    while (arr.length) {
        let j = arr.lastIndexOf(arr[0]);
        if (j === 0) { arr.shift(); continue; }
        ans += arr.length - 1 - j;
        arr.splice(j, 1);
        arr.shift();
    }
    return ans;
};
